import * as THREE from 'three/webgpu'
import { nodes } from 'three/tsl'
import { gsap } from 'gsap'
import { createTextMesh } from '@/text'

function createVerticalGradientTexture (stops, width = 256, height = 256) {
  const size = width * height * 4
  const data = new Uint8Array(size)

  const lerp = (a, b, t) => a + (b - a) * t
  const hexToRgb = (hex) => {
    const int = parseInt(hex.slice(1), 16)
    return [(int >> 16) & 255, (int >> 8) & 255, int & 255]
  }

  // sort stops just in case
  stops = stops.slice().sort((a, b) => a.at - b.at)

  for (let y = 0; y < height; y++) {
    const v = y / (height - 1)

    // find surrounding stops
    let i0 = 0
    while (i0 < stops.length - 1 && v > stops[i0 + 1].at) i0++
    let i1 = Math.min(i0 + 1, stops.length - 1)

    const s0 = stops[i0]
    const s1 = stops[i1]
    const t = (v - s0.at) / (s1.at - s0.at || 1)

    const c0 = hexToRgb(s0.hex)
    const c1 = hexToRgb(s1.hex)

    const r = Math.round(lerp(c0[0], c1[0], t))
    const g = Math.round(lerp(c0[1], c1[1], t))
    const b = Math.round(lerp(c0[2], c1[2], t))

    for (let x = 0; x < width; x++) {
      const idx = (y * width + x) * 4
      data[idx] = r
      data[idx + 1] = g
      data[idx + 2] = b
      data[idx + 3] = 255
    }
  }

  const tex = new THREE.DataTexture(data, width, height, THREE.RGBAFormat)
  tex.needsUpdate = true
  tex.minFilter = THREE.LinearFilter
  tex.magFilter = THREE.LinearFilter
  tex.wrapS = THREE.ClampToEdgeWrapping
  tex.wrapT = THREE.ClampToEdgeWrapping
  return tex
}

function createRadialGradientTexture (radius = 1, size = 256) {
  const data = new Uint8Array(size * size * 4)

  const center = size / 2
  const maxDist = radius * size / 2

  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - center
      const dy = y - center
      const dist = Math.sqrt(dx * dx + dy * dy)
      const t = THREE.MathUtils.clamp(1 - dist / maxDist, 0, 1)

      const opacity = t * 0.6 // center opacity 0.6 fading to 0

      const idx = (y * size + x) * 4
      data[idx] = 255
      data[idx + 1] = 255
      data[idx + 2] = 255
      data[idx + 3] = Math.round(opacity * 255)
    }
  }

  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat)
  tex.needsUpdate = true
  tex.minFilter = THREE.LinearFilter
  tex.magFilter = THREE.LinearFilter
  tex.wrapS = THREE.ClampToEdgeWrapping
  tex.wrapT = THREE.ClampToEdgeWrapping
  tex.transparent = true
  return tex
}

/**
 * @param {Object} config
 * @param {Object} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode (config, ctx) {
  const group = new THREE.Group()
  group.position.set(0, 0, 0)
  group.rotation.set(0, 0, 0)
  group.scale.set(1, 1, 1)

  // ---------- Textures ----------
  const brushedTex = ctx.textureLoader('/prism-assets/chrome/brushed-metal.map.png')
  brushedTex.wrapS = THREE.RepeatWrapping
  brushedTex.wrapT = THREE.RepeatWrapping

  // ---------- Torus Knot ----------
  const knotGeom = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36)
  const knotMat = new THREE.MeshPhysicalMaterial({
    map: brushedTex,
    roughness: 0.55,
    metalness: 0.55,
    clearcoat: 0.22,
    clearcoatRoughness: 0.35,
    anisotropy: 0.9,
    anisotropyDirection: new THREE.Vector2(0, 1) // rotated 90° to tube direction
  })
  // add 2% jitter to roughness
  knotMat.roughness = knotMat.roughness * (0.98 + Math.random() * 0.04)

  const knotMesh = new THREE.Mesh(knotGeom, knotMat)
  knotMesh.position.set(0, 0.4, 0)
  group.add(knotMesh)

  // ---------- Pedestal ----------
  const pedGeom = new THREE.CylinderGeometry(1.1, 1.1, 0.5, 32, 1, false)
  const pedMat = new THREE.MeshStandardMaterial({
    color: new THREE.Color('#14141a'),
    roughness: 0.7,
    metalness: 0.35
  })
  const pedMesh = new THREE.Mesh(pedGeom, pedMat)
  // top face at y = -0.35 => center at -0.35 - 0.25 = -0.6
  pedMesh.position.set(0, -0.6, 0)
  group.add(pedMesh)

  // ---------- Contact Shadow ----------
  const shadowGeom = new THREE.PlaneGeometry(3, 3)
  const shadowTex = createRadialGradientTexture(1.5, 256)
  const shadowMat = new THREE.MeshBasicMaterial({
    map: shadowTex,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
    opacity: 1
  })
  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMat)
  shadowMesh.rotation.x = -Math.PI / 2
  shadowMesh.position.set(0, -0.36, 0)
  group.add(shadowMesh)

  // ---------- Backdrop ----------
  const backdropGeom = new THREE.PlaneGeometry(7, 6)
  const backdropTex = createVerticalGradientTexture([
    { at: 0, hex: '#0b0b10' },
    { at: 0.7, hex: '#101017' },
    { at: 1, hex: '#16161d' }
  ])
  const backdropMat = new THREE.MeshBasicMaterial({
    map: backdropTex,
    transparent: true,
    side: THREE.DoubleSide
  })
  const backdropMesh = new THREE.Mesh(backdropGeom, backdropMat)
  backdropMesh.position.set(0, 0, -3)
  group.add(backdropMesh)

  // ---------- Lighting ----------
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2)
  keyLight.position.set(2, 4, 2)
  group.add(keyLight)

  const fillLight = new THREE.AmbientLight(0xffffff, 0.3)
  group.add(fillLight)

  // ---------- Text ----------
  const headline = createTextMesh(ctx.fontAtlas, {
    text: 'Material study 03',
    fontFamily: 'Lora',
    fontWeight: 600,
    fontSize: 68,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    color: '#e8ecf2',
    atlasRegion: { atlas: 0, rect: [0, 0, 512, 320] }
  })
  headline.position.set(0, -1.2, 0.01)
  group.add(headline)

  const caption = createTextMesh(ctx.fontAtlas, {
    text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT',
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 18,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
    atlasRegion: { atlas: 0, rect: [0, 0, 512, 320] }
  })
  caption.position.set(0, -1.6, 0.01)
  group.add(caption)

  // ---------- Cinematic Primitives ----------
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name]
      if (typeof fn === 'function') {
        fn(group, prim.params)
      }
    }
  }

  // ---------- Cleanup ----------
  const disposables = [brushedTex, shadowTex, backdropTex]
  group.userData.cleanup = () => {
    disposables.forEach(t => {
      if (t && t.dispose) t.dispose()
    })
    // kill any GSAP timelines we may have started (none in this node)
    gsap.globalTimeline.clear()
    // remove handlers placeholder
    group.userData.handlers = {}
  }

  // ---------- Event Handlers placeholder ----------
  group.userData.handlers = {}

  return group
}
